import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"Sharing a form","description":"Make forms available via link, QR code, or embedded on your own website.","frontmatter":{"title":"Sharing a form","description":"Make forms available via link, QR code, or embedded on your own website."},"headers":[],"relativePath":"en/formulare/formular-teilen.md","filePath":"en/formulare/formular-teilen.md","lastUpdated":1787319236000}'),n={name:"en/formulare/formular-teilen.md"};function i(s,e,l,d,h,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="sharing-a-form" tabindex="-1">Sharing a form <a class="header-anchor" href="#sharing-a-form" aria-label="Permalink to &quot;Sharing a form&quot;">​</a></h1><p>A form only becomes reachable once you generate a share link. Until then, it only exists in the editor.</p><h2 id="generating-a-link" tabindex="-1">Generating a link <a class="header-anchor" href="#generating-a-link" aria-label="Permalink to &quot;Generating a link&quot;">​</a></h2><p>Click <strong>Create link</strong> in the form editor.</p><p>The <em>Share your form</em> dialog opens, noting that the form has been published securely. The dialog has three tabs: <strong>Link</strong>, <strong>QR code</strong>, and <strong>Open in app</strong>.</p><div class="danger custom-block"><p class="custom-block-title">A share link is public by default</p><p>Without an additional restriction, <strong>anyone with the link</strong> can open and submit the form. The link isn&#39;t guessable, but it&#39;s also unprotected — if it gets forwarded, it keeps working.</p><p>Before distributing a link, decide who should be allowed access via <strong>Set restrictions</strong>. See <a href="/en/zusammenarbeit/zugriff-beschraenken">Access to shared content</a>.</p></div><h2 id="the-link-tab" tabindex="-1">The &quot;Link&quot; tab <a class="header-anchor" href="#the-link-tab" aria-label="Permalink to &quot;The &quot;Link&quot; tab&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Button</th><th>Function</th></tr></thead><tbody><tr><td><strong>Copy</strong></td><td>Copies the link to the clipboard</td></tr><tr><td><strong>Preview in new tab</strong></td><td>Opens the form as people filling it out will see it</td></tr><tr><td><strong>Set restrictions</strong></td><td>Defines who&#39;s allowed access</td></tr><tr><td><strong>Share form prefilled</strong></td><td>Generates a link with preset values</td></tr><tr><td><strong>Add link</strong></td><td>Creates another, independent link</td></tr></tbody></table><h3 id="multiple-links-to-the-same-form" tabindex="-1">Multiple links to the same form <a class="header-anchor" href="#multiple-links-to-the-same-form" aria-label="Permalink to &quot;Multiple links to the same form&quot;">​</a></h3><p><strong>Add link</strong> lets you generate several named links to the same form. The <em>New link</em> dialog asks for a name.</p><div class="tip custom-block"><p class="custom-block-title">What multiple links are useful for</p><p>Each link can be named, restricted, and removed individually. That lets you separate channels: one link for the newsletter, one for the website, one for a trade show booth. When a campaign ends, you remove just that one link — the others stay valid.</p><p>How many additional links are possible depends on your plan.</p></div><p>All links in a Space are collected under <a href="/en/zusammenarbeit/externe-links">Overview of external links</a>.</p><h2 id="the-qr-code-tab" tabindex="-1">The &quot;QR code&quot; tab <a class="header-anchor" href="#the-qr-code-tab" aria-label="Permalink to &quot;The &quot;QR code&quot; tab&quot;">​</a></h2><p>The QR code leads directly to the form. The dialog explains: <em>Scan this QR code with your smartphone&#39;s camera to open the form directly.</em></p><p>You can customize:</p><ul><li><strong>Style</strong> — <em>Squares</em>, <em>Dots</em>, or <em>Rounded</em></li><li><strong>Color</strong></li></ul><p>You can download the code as <strong>PNG</strong> or <strong>SVG</strong>.</p><div class="tip custom-block"><p class="custom-block-title">PNG or SVG?</p><p>PNG is fine for screens and email. For print — posters, stands, packaging — use SVG: the format stays sharp at any size.</p><p>The SVG download is plan-dependent.</p></div><div class="warning custom-block"><p class="custom-block-title">QR codes on printed material</p><p>A printed QR code can&#39;t be recalled. If you delete the form or the link, the code leads nowhere. For printed material, use a dedicated, named link that you keep in place permanently.</p></div><h2 id="the-open-in-app-tab" tabindex="-1">The &quot;Open in app&quot; tab <a class="header-anchor" href="#the-open-in-app-tab" aria-label="Permalink to &quot;The &quot;Open in app&quot; tab&quot;">​</a></h2><p>Shows a QR code that adds the form to the mobile app, along with links to the App Store and Google Play.</p><h2 id="embedding-on-your-own-website" tabindex="-1">Embedding on your own website <a class="header-anchor" href="#embedding-on-your-own-website" aria-label="Permalink to &quot;Embedding on your own website&quot;">​</a></h2><p><strong>Embed on your website</strong> generates the embed code.</p><p>Settings:</p><ul><li><strong>Auto-adjust height</strong> — the height follows the form&#39;s content</li><li><strong>Smartphone preview</strong> and <strong>Computer preview</strong> — check before you embed</li></ul><p>You&#39;ll find the finished code under <em>Embed code</em>. Copy it into your website.</p><div class="tip custom-block"><p class="custom-block-title">Turn on auto-adjust height</p><p>Without this option, the embedded form gets a fixed height. With multi-page forms or expanding fields, a scrollbar appears inside the frame — unsightly and hard to use on mobile.</p></div><h2 id="prefilled-links" tabindex="-1">Prefilled links <a class="header-anchor" href="#prefilled-links" aria-label="Permalink to &quot;Prefilled links&quot;">​</a></h2><p><strong>Share form prefilled</strong> opens an editor where you fill out the form yourself. The entered values produce a link that opens the form already filled in.</p><p>The dialog explains: <em>Please enter the data in the corresponding form fields. Copy the generated link and use it to share the form with the prefilled data quickly and easily.</em></p><p>Typical uses:</p><ul><li>Distinguishing campaigns (hidden field <em>Source</em>)</li><li>Prefilling recurring information (location, department, event)</li><li>Starting a Flow with fixed values</li></ul><p>→ <a href="/en/formulare/vorausgefuellte-links">Prefilled links</a></p><h2 id="sharing-a-single-entry-for-editing" tabindex="-1">Sharing a single entry for editing <a class="header-anchor" href="#sharing-a-single-entry-for-editing" aria-label="Permalink to &quot;Sharing a single entry for editing&quot;">​</a></h2><p>Besides creating new entries, forms can also make <strong>existing entries</strong> editable. You don&#39;t generate that link here, but from the entry itself via <strong>Share entry</strong>.</p><p>This requires a matching form — without one, a notice appears telling you to create one first.</p><p>→ <a href="/en/formulare/eintraege-bearbeiten">Editing entries via form</a></p><h2 id="removing-a-link" tabindex="-1">Removing a link <a class="header-anchor" href="#removing-a-link" aria-label="Permalink to &quot;Removing a link&quot;">​</a></h2><p>Remove a link from the share dialog or via the <a href="/en/zusammenarbeit/externe-links">links overview</a> of the Space.</p><div class="warning custom-block"><p class="custom-block-title">Removal takes effect immediately</p><p>A removed link stops working right away — even for people who saved it or currently have it open. Entries already submitted are of course preserved.</p></div><h2 id="when-a-form-isn-t-reachable" tabindex="-1">When a form isn&#39;t reachable <a class="header-anchor" href="#when-a-form-isn-t-reachable" aria-label="Permalink to &quot;When a form isn&#39;t reachable&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Meaning</th></tr></thead><tbody><tr><td><em>Access to this form is restricted.</em></td><td>An access restriction applies that this person doesn&#39;t meet</td></tr><tr><td><em>Warning: Potentially risky form</em></td><td>The form has been flagged as possibly abusive</td></tr><tr><td><em>This form is locked</em></td><td>The form has been locked</td></tr></tbody></table><p>For the last two, contact <code>abuse@apptivegrid.com</code> if you&#39;d like to request a review.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/zusammenarbeit/zugriff-beschraenken">Access to shared content</a></li><li><a href="/en/formulare/vorausgefuellte-links">Prefilled links</a></li><li><a href="/en/zusammenarbeit/externe-links">Overview of external links</a></li></ul>',45)])])}const u=t(n,[["render",i]]);export{c as __pageData,u as default};
